"""Vectoriser/classifier factories, metric computation and timings (R5, R8-R12)."""
from __future__ import annotations

import time
import warnings

import numpy as np
import pandas as pd
from sklearn.exceptions import ConvergenceWarning
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.metrics import (accuracy_score, confusion_matrix, f1_score,
                             precision_recall_fscore_support)
from sklearn.svm import LinearSVC

from . import config


def make_vectorizer():
    return TfidfVectorizer(**config.TFIDF_PARAMS)


def make_svc(max_iter=None):
    params = dict(config.SVC_PARAMS)
    if max_iter is not None:
        params["max_iter"] = max_iter
    return LinearSVC(**params)


class Timer:
    def __init__(self):
        self.t = {}

    def __enter__(self):
        self._start = time.perf_counter()
        return self

    def __exit__(self, *exc):
        self.elapsed = time.perf_counter() - self._start

    def lap(self, name):
        now = time.perf_counter()
        self.t[name] = now - getattr(self, "_last", getattr(self, "_start", now))
        self._last = now
        return self.t[name]


def fit_classifier(clf, X, y):
    """Fit, retrying once with a larger max_iter if scikit-learn fails to converge (A3)."""
    used = clf.max_iter
    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter("always", ConvergenceWarning)
        clf.fit(X, y)
    if any(issubclass(w.category, ConvergenceWarning) for w in caught):
        used = config.SVC_MAX_ITER_FALLBACK
        clf = make_svc(max_iter=used)
        with warnings.catch_warnings(record=True) as caught2:
            warnings.simplefilter("always", ConvergenceWarning)
            clf.fit(X, y)
        converged = not any(issubclass(w.category, ConvergenceWarning) for w in caught2)
    else:
        converged = True
    assert np.isfinite(clf.coef_).all()
    clf.max_iter_used = used
    clf.converged = converged
    return clf


def margins(clf, X) -> np.ndarray:
    """Highest decision score minus the second-highest (R12)."""
    scores = clf.decision_function(X)
    if scores.ndim == 1:  # binary edge case
        scores = np.column_stack([-scores, scores])
    part = np.partition(scores, -2, axis=1)
    return part[:, -1] - part[:, -2]


def evaluate(y_true, y_pred, labels, scores=None) -> dict:
    labels = list(labels)
    pr, rc, f1, sup = precision_recall_fscore_support(
        y_true, y_pred, labels=labels, zero_division=config.ZERO_DIVISION)
    res = {
        "accuracy": float(accuracy_score(y_true, y_pred)),
        "macro_f1": float(f1_score(y_true, y_pred, labels=labels, average="macro",
                                   zero_division=config.ZERO_DIVISION)),
        "weighted_f1": float(f1_score(y_true, y_pred, labels=labels, average="weighted",
                                      zero_division=config.ZERO_DIVISION)),
        "n_records": int(len(y_true)),
        "per_label": {
            lab: {"precision": float(pr[i]), "recall": float(rc[i]),
                  "f1": float(f1[i]), "support": int(sup[i])}
            for i, lab in enumerate(labels)
        },
        "confusion_matrix": confusion_matrix(y_true, y_pred, labels=labels).tolist(),
    }
    if scores is not None:
        m = margins_from_scores(scores)
        correct = np.asarray(y_true) == np.asarray(y_pred)
        res["margin"] = {
            "mean": float(m.mean()),
            "median": float(np.median(m)),
            "mean_correct": float(m[correct].mean()) if correct.any() else None,
            "mean_incorrect": float(m[~correct].mean()) if (~correct).any() else None,
        }
    return res


def margins_from_scores(scores: np.ndarray) -> np.ndarray:
    if scores.ndim == 1:
        scores = np.column_stack([-scores, scores])
    part = np.partition(scores, -2, axis=1)
    return part[:, -1] - part[:, -2]


def dummy_baseline(y_train, y_dev, labels) -> dict:
    from sklearn.dummy import DummyClassifier
    d = DummyClassifier(strategy="most_frequent")
    d.fit(np.zeros((len(y_train), 1)), y_train)
    pred = d.predict(np.zeros((len(y_dev), 1)))
    return {
        "accuracy": float(accuracy_score(y_dev, pred)),
        "macro_f1": float(f1_score(y_dev, pred, labels=list(labels), average="macro",
                                   zero_division=config.ZERO_DIVISION)),
        "majority_class": str(d.classes_[0]),
    }


def save_predictions(path, ids, y_true, y_pred, margin, event):
    df = pd.DataFrame({"id": ids, "event": event, "y_true": y_true,
                       "y_pred": y_pred, "margin": margin})
    df.to_csv(path, index=False, compression="gzip")
    return str(path)

